                            name
                        ),
                        severity: Severity::Error,
                        byte_range: lhs.byte_range(),
                        line: pos.row + 1,
                        column: pos.column + 1,
                        fix: None,
                    });
                    redef_reported.insert(name.clone());
                }
                variable_names.insert(name);
